                    int n, int m, int k, float alpha, float beta)
{
  dim3 grid(n / TILE_DIM, n / TILE_DIM);
  dim3 block(TILE_DIM, 2);
  transposeWarpRegister16<<<grid, block>>>(C, A, n);
}

